//! Compatibility vectors of the data sub-documents (`jobs`, `settings`, `layout`, `order-state`):
//! the engine against what `applyOp` of `@cv/mutations` does.
//!
//! `tests/vectors/v7-data.json` is generated by `lib/mutations/scripts/ccvl-data-vectors.ts` in
//! `CareerVector` (see its header). Each case starts from a Yjs update, applies one op as an actor,
//! and compares the structure of the sub-document root, the changed row keys, that the Yjs bytes
//! the TypeScript produced reach the same structure here, or the exact refusal.
//! `CCVL_VECTOR_OUT=<dir>` also writes the update bytes this engine produced, for
//! `ccvl-data-verify-rust.ts` (the other direction).
#![cfg(feature = "doc")]

use base64::Engine as _;
use ccvl::doc::{ActorClass, Doc, OP_CATALOG_VERSION};
use serde_json::{Map, Value, json};

const VECTORS: &str = include_str!("vectors/v7-data.json");

fn decode(text: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD
        .decode(text)
        .expect("vector bytes are base64")
}

fn root_of(sub: &str) -> &'static str {
    match sub {
        "jobs" => "jobs",
        "settings" => "settings",
        "layout" => "layout",
        "order-state" => "order_state",
        other => panic!("unknown sub-document {other}"),
    }
}

/// The document of a case: scoped to its root, holding the pre-state.
fn load(root: &str, pre: &[u8]) -> Doc {
    let mut doc = Doc::scoped_data(root).expect("a data root");
    doc.receive(pre).expect("pre-state loads");
    doc
}

/// `Doc::shape` leaves empty roots out; the vectors dump the root itself.
fn wrapped(root: &str, shape: &Value) -> Value {
    if shape == &json!({ "$map": {} }) {
        json!({})
    } else {
        json!({ root: shape })
    }
}

fn assert_shape(case: &str, what: &str, doc: &Doc, root: &str, expected: &Value) {
    assert_eq!(
        doc.shape(),
        wrapped(root, expected),
        "{case} ({what}): structure differs"
    );
}

#[test]
fn data_ops_match_yjs() {
    let file: Value = serde_json::from_str(VECTORS).expect("vector file is JSON");
    assert_eq!(file["source"]["op_catalog_version"], OP_CATALOG_VERSION);
    let out_dir = std::env::var_os("CCVL_VECTOR_OUT").map(std::path::PathBuf::from);
    let mut produced = Map::new();
    let cases = file["cases"].as_array().expect("cases");
    assert!(cases.len() >= 50, "expected the full suite");
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let root = root_of(case["sub"].as_str().expect("sub"));
        let pre = decode(case["pre"].as_str().expect("pre"));
        let actor = ActorClass::parse(case["actor"].as_str().expect("actor")).expect("actor");
        let actor_id = case.get("actor_id").and_then(Value::as_str);
        let expect = &case["expect"];
        let mut doc = load(root, &pre);
        let before = doc.shape();
        let result = doc.apply_op_for(&case["op"], actor, actor_id);
        if expect["ok"] == json!(true) {
            let changed = result.unwrap_or_else(|e| panic!("{name}: engine refused: {e}"));
            assert_shape(name, "engine", &doc, root, &expect["shape"]);
            let mut keys: Vec<String> = changed
                .nodes
                .iter()
                .map(|n| {
                    assert_eq!(n.branch, root, "{name}: branch");
                    n.path[0].clone()
                })
                .collect();
            keys.sort();
            keys.dedup();
            let expected: Vec<String> = expect["changed"]
                .as_array()
                .expect("changed")
                .iter()
                .map(|k| k.as_str().expect("key").to_string())
                .collect();
            assert_eq!(keys, expected, "{name}: changed rows");
            // The bytes Yjs produced decode here and give the same document.
            let mut peer = load(root, &pre);
            peer.receive(&decode(expect["diff_update"].as_str().expect("diff")))
                .unwrap_or_else(|e| panic!("{name}: Yjs update refused: {e}"));
            assert_shape(name, "Yjs update", &peer, root, &expect["shape"]);
            if out_dir.is_some() {
                let bytes = doc.take_outgoing().expect("outgoing");
                produced.insert(
                    name.to_string(),
                    json!(base64::engine::general_purpose::STANDARD.encode(bytes)),
                );
            }
        } else {
            let error = result.expect_err(&format!("{name}: the engine should refuse"));
            assert_eq!(
                error.message(),
                expect["error"].as_str().expect("error"),
                "{name}: refusal"
            );
            // The TypeScript side recorded that the refused op left its document untouched; the engine must too.
            assert_eq!(
                expect["unchanged"],
                json!(true),
                "{name}: the vector must record an unchanged document"
            );
            assert_eq!(
                doc.shape(),
                before,
                "{name}: refused op changed the document"
            );
            assert!(
                doc.take_outgoing().expect("outgoing").is_empty(),
                "{name}: refused op produced bytes"
            );
        }
    }
    if let Some(dir) = out_dir {
        std::fs::create_dir_all(&dir).expect("out dir");
        std::fs::write(
            dir.join("data-rust-out.json"),
            serde_json::to_string(&produced).expect("json"),
        )
        .expect("write");
    }
}

#[test]
fn an_op_of_another_sub_document_is_refused() {
    let mut jobs = Doc::scoped_data("jobs").expect("jobs");
    let err = jobs
        .apply_op(&json!({ "kind": "settings.update", "patch": { "a": 1 } }))
        .expect_err("settings.update on the jobs document");
    assert_eq!(
        err.message(),
        "settings.update: 'settings' is not part of this document"
    );
    let mut profile = Doc::scoped("cv_profile").expect("profile");
    let err = profile
        .apply_op(&json!({ "kind": "job.delete", "job_id": "x" }))
        .expect_err("job.delete on a profile document");
    assert_eq!(
        err.message(),
        "job.delete: 'jobs' is not part of this document"
    );
}

#[test]
fn rows_and_ids_read_the_visible_window() {
    let mut doc = Doc::scoped_data("jobs").expect("jobs");
    for n in 1..=3 {
        doc.apply_op(&json!({
            "kind": "job.create",
            "url": format!("https://example.com/jobs/{n}"),
            "attributes": { "n": n, "evaluations": { "fit": n } }
        }))
        .expect("create");
    }
    let ids = doc.row_ids("jobs").expect("ids");
    assert_eq!(ids.len(), 3);
    let window = doc
        .rows("jobs", Some(&[ids[1].clone(), "job_absent".to_string()]))
        .expect("rows");
    let rows = window.as_object().expect("object");
    assert_eq!(rows.len(), 1);
    let row = &rows[&ids[1]];
    assert!(
        row["url"]
            .as_str()
            .expect("url")
            .starts_with("https://example.com/jobs/")
    );
    assert!(row["attributes"]["evaluations"]["fit"].is_number());
    assert!(doc.rows("settings", None).is_err());
}

/// Real production settings hold a key set to `undefined` (a JavaScript client wrote it). In JSON
/// that key is absent, exactly as `JSON.stringify(map.toJSON())` has it: the rows must not show it
/// as `null`, or a reader that tells `null` from absent sees another document.
#[test]
fn a_key_holding_undefined_is_absent_in_rows() {
    use yrs::{Any, Map, ReadTxn, Transact};
    let source = yrs::Doc::new();
    {
        let settings = source.get_or_insert_map("settings");
        let mut txn = source.transact_mut();
        settings.insert(&mut txn, "views", Any::Undefined);
        settings.insert(&mut txn, "theme", "dark");
        settings.insert(&mut txn, "off", Any::Null);
    }
    let update = {
        source
            .transact()
            .encode_state_as_update_v1(&yrs::StateVector::default())
    };
    let doc = load("settings", &update);
    let rows = doc.rows("settings", None).expect("rows");
    assert_eq!(rows, json!({ "theme": "dark", "off": null }));
}
